solution:
def can_balance(s: str) -> bool:
    low = high = 0                       # fewest and most '(' that could be open
    for ch in s:
        if ch == '(':
            low, high = low + 1, high + 1
        elif ch == ')':
            low, high = low - 1, high - 1
        else:                            # '*' closes one, adds nothing or opens one
            low, high = low - 1, high + 1
        if high < 0:                     # even with every star as '(' a ')' is unmatched
            return False
        low = max(low, 0)                # a star never has to close what isn't open
    return low == 0

perf.naive:
def can_balance(s: str) -> bool:
    opens = {0}                          # every possible count of open '('
    for ch in s:
        if ch == '(':
            opens = {o + 1 for o in opens}
        elif ch == ')':
            opens = {o - 1 for o in opens if o > 0}
        else:
            opens = {o + d for o in opens for d in (-1, 0, 1) if o + d >= 0}
        if not opens:
            return False
    return 0 in opens
